import{_ as a,o as r,c as s,a3 as t}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"HADash v0.9.4 Preview","description":"HADash erhält eine vereinfachte Windows-Oberfläche ohne eigenes Theme-System.","frontmatter":{"title":"HADash v0.9.4 Preview","description":"HADash erhält eine vereinfachte Windows-Oberfläche ohne eigenes Theme-System.","date":"2026-08-02T00:00:00.000Z","author":"UGSo Software","tags":["HADash","Home Assistant","Windows"]},"headers":[],"relativePath":"blog/posts/hadash-preview.md","filePath":"blog/posts/hadash-preview.md","lastUpdated":1793126673000}'),n={name:"blog/posts/hadash-preview.md"};function i(o,e,h,l,d,u){return r(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="hadash-v0-9-4-preview" tabindex="-1">HADash v0.9.4 Preview <a class="header-anchor" href="#hadash-v0-9-4-preview" aria-label="Permalink to &quot;HADash v0.9.4 Preview&quot;">​</a></h1><p><strong>2. August 2026 · HADash</strong></p><p>Mit der Version <strong>v0.9.4-preview</strong> wurde die Benutzeroberfläche von HADash vereinfacht.</p><h2 id="was-wurde-geandert" tabindex="-1">Was wurde geändert? <a class="header-anchor" href="#was-wurde-geandert" aria-label="Permalink to &quot;Was wurde geändert?&quot;">​</a></h2><p>Das bisherige Theme-System wurde vollständig entfernt. HADash verwendet jetzt wieder die Standardfarben und Steuerelemente von Windows.</p><p>Dadurch wird die Oberfläche:</p><ul><li>übersichtlicher</li><li>besser lesbar</li><li>weniger fehleranfällig</li><li>konsistenter mit anderen Windows-Anwendungen</li></ul><h2 id="hadash" tabindex="-1">HADash <a class="header-anchor" href="#hadash" aria-label="Permalink to &quot;HADash&quot;">​</a></h2><p>HADash ist ein portables Windows-Programm zum Einlesen, Sichern und Exportieren von Home-Assistant-Dashboards.</p><p>Das Programm kann unter anderem:</p><ul><li>JSON-Daten aus unverschlüsselten Home-Assistant-Backups einlesen</li><li>Inhalte aus dem <code>.storage</code>-Ordner verarbeiten</li><li>komplette Dashboards als YAML speichern</li><li>einzelne Ansichten auswählen und exportieren</li><li>Ansichten als TXT, YAML oder vollständiges Dashboard sichern</li></ul><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><p>Die aktuelle Preview-Version ist über GitHub verfügbar:</p><p><a href="https://github.com/rockbaer2007/HADash/releases" target="_blank" rel="noreferrer">HADash Releases öffnen</a></p><h2 id="dokumentation" tabindex="-1">Dokumentation <a class="header-anchor" href="#dokumentation" aria-label="Permalink to &quot;Dokumentation&quot;">​</a></h2><p><a href="/projects/hadash/">Zur HADash-Dokumentation</a></p>',16)])])}const m=a(n,[["render",i]]);export{c as __pageData,m as default};
